import{b as d,O as e,g as s,j as o}from"./chunks/framework.DSt9LnBW.js";const g=JSON.parse('{"title":"性能测试报告指标解读：报告里每一列到底在说什么","description":"JMeter 跑完，报告出来了——样本、失败数、异常%、平均、最小、最大、中位数、90th/95th/99th 百分位、吞吐量……一排列过去，很多人只会盯「平均值」，然后得出一个不太靠谱的结论。","frontmatter":{"date":"2026-08-16T00:00:00.000Z","tags":["性能测试","指标","压测"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/performance-testing/performance-report-metrics/index.md","filePath":"个人博客/性能测试/1.性能测试报告指标解读.md","lastUpdated":1789784116000}'),r={name:"blog/performance-testing/performance-report-metrics/index.md"};function a(n,t,p,c,i,h){return e(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="性能测试报告指标解读-报告里每一列到底在说什么" tabindex="-1">性能测试报告指标解读：报告里每一列到底在说什么 <a class="header-anchor" href="#性能测试报告指标解读-报告里每一列到底在说什么" aria-label="Permalink to &quot;性能测试报告指标解读：报告里每一列到底在说什么&quot;">​</a></h1><p>JMeter 跑完，报告出来了——样本、失败数、异常%、平均、最小、最大、中位数、90th/95th/99th 百分位、吞吐量……一排列过去，很多人只会盯「平均值」，然后得出一个不太靠谱的结论。</p><p>这篇不空讲定义，直接拿一份真实报告，把每一列拆开看：它是什么、在我们这组数据里长什么样、什么地方最容易读错。</p><h2 id="一、这次压的是什么" tabindex="-1">一、这次压的是什么 <a class="header-anchor" href="#一、这次压的是什么" aria-label="Permalink to &quot;一、这次压的是什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>被测对象</td><td>testing-online（本地练习站，React + Express，内存数据）</td></tr><tr><td>压测接口</td><td><code>POST /api/perf/generate</code>（批量生成用户数据）</td></tr><tr><td>档位</td><td>10 / 20 / 50 并发，三档分开跑</td></tr><tr><td>每档配置</td><td>Ramp-Up 5s，循环「永远」，持续 10 秒</td></tr><tr><td>执行方式</td><td>命令行 <code>jmeter -n -t users-generate.jmx -l result.jtl -e</code></td></tr></tbody></table><p>脚本怎么搭、参数为什么这么配，在《用 JMeter 压一把接口》里写过。这篇只看报告本身。</p><p><img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-05-thread-group.webp" alt="JMeter 线程组参数"></p><h2 id="二、先说报告长什么样" tabindex="-1">二、先说报告长什么样 <a class="header-anchor" href="#二、先说报告长什么样" aria-label="Permalink to &quot;二、先说报告长什么样&quot;">​</a></h2><p>同一次压测，JMeter 能给出三种视图，<strong>它们的列并不一样</strong>——这一点特别容易踩坑。</p><p><strong>GUI 里的汇总报告</strong>——最基础的一张表，但列最少：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 样本 | 平均值 | 最小值 | 最大值 | 标准偏差 | 平均字节数 | 异常 % | 吞吐量 | 接收 KB/sec | 发送 KB/sec</span></span></code></pre></div><p><strong>GUI 里的聚合报告</strong>——比汇总报告多了中位数和百分位：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 样本 | 平均值 | 中位数 | 90% 百分位 | 95% 百分位 | 99% 百分位 | 最小值 | 最大值 | 异常 % | 吞吐量 | 接收 KB/sec | 发送 KB/sec</span></span></code></pre></div><blockquote><p>想在上面的表里看到 90% / 95% / 99%，得添加<strong>聚合报告</strong>——汇总报告是没有这三列的。</p></blockquote><p><strong>命令行生成的 HTML 报告</strong>——数据一样，但多了图形化总览，信息量最大：</p><p><img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-09-dashboard.webp" alt="JMeter HTML 报告总览"></p><p>下面拆解以 HTML 报告里的 <strong>Statistics</strong> 表为主线（它列最全，表头分成四组），中途也会补上只有 GUI 报告才有的列：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Requests / Executions | Response Times (ms)        | Throughput      | Network (KB/sec)</span></span>
<span class="line"><span>#Samples  FAIL  Error% | Average Min Max Median 90th 95th 99th | Transactions/s | Received  Sent</span></span></code></pre></div><p><img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-06-report-10.webp" alt="JMeter HTML 报告 Statistics 表"></p><h2 id="三、逐列拆解" tabindex="-1">三、逐列拆解 <a class="header-anchor" href="#三、逐列拆解" aria-label="Permalink to &quot;三、逐列拆解&quot;">​</a></h2><p>下面从「发了多少请求」一路讲到「报告看不到的部分」，共 11 项。<strong>只想看最要紧的</strong>，可以只读样本数、失败数/异常%、百分位、吞吐量这四项。</p><h3 id="样本数-samples" tabindex="-1">样本数（#Samples） <a class="header-anchor" href="#样本数-samples" aria-label="Permalink to &quot;样本数（#Samples）&quot;">​</a></h3><p>指这个标签下总共发出了多少个请求。三档业务行分别是 <strong>130,280 / 127,700 / 123,486</strong>。</p><blockquote><p><strong>先说一个全篇通用的前提：报告里有「Total 行」和「业务行」，本文一律读业务行。</strong></p><p>Total 行会把每个标签都算进去——这次是登录、生成用户、清理各一次，所以是 130,282。听起来只多 2 个样本，影响却不小：<strong>Total 行的最大值是 16ms，业务行只有 5ms</strong>（那 16ms 来自一次性的「登录请求」，不是业务接口的真实表现）；Total 行的吞吐量 12,657 也低于业务行的 13,027。</p><p>所以下面出现的每个数字，都是「生成用户压测」这一行。</p></blockquote><p>这里要建立的第一个直觉是：<strong>样本数不等于线程数</strong>。三档线程数是 10 / 20 / 50，样本数却是十几万——因为循环选了「永远」，每个线程在 10 秒里一直在打，不是打一次就走。</p><p>反过来也要留个心眼：如果线程数是 10、样本数也刚好是 10，那多半是「循环 1」——线程打完一个请求就退出了，根本不存在并发。</p><h3 id="失败数-fail-与异常-error" tabindex="-1">失败数（FAIL）与异常%（Error %） <a class="header-anchor" href="#失败数-fail-与异常-error" aria-label="Permalink to &quot;失败数（FAIL）与异常%（Error %）&quot;">​</a></h3><p><code>FAIL</code> 是失败样本的绝对个数，<code>Error %</code> 是它的占比。三档的 FAIL 都是 <strong>0</strong>、Error % 都是 <strong>0.00%</strong>，说明这 38 万次请求没有一次超时、5xx 或连接失败。</p><p>这两个指标的地位比较特殊：<strong>响应慢只是体验问题，报错是功能不可用</strong>。所以打开报告第一眼看它，非 0 就先别谈性能。</p><p><strong>最省事的看法是右上那个 Requests Summary 饼图</strong>——它把这两个数画成一个圆：绿色的 <code>PASS</code> 占 100%，红色的 <code>FAIL</code> 占 0%（数据来自报告里的 <code>{&quot;OkPercent&quot;:100.0, &quot;KoPercent&quot;:0.0}</code>）。饼图一眼就能看懂，适合截图发群里；要精确数字，还是看 Statistics 表的 <code>Error %</code>。</p><p><strong>那非 0 的时候，去哪儿查？</strong> 报告里就有两张现成的表，不用回去翻脚本：</p><table tabindex="0"><thead><tr><th>面板</th><th>列</th><th>回答什么问题</th></tr></thead><tbody><tr><td><code>Errors</code></td><td>Type of error · Number of errors · % in errors · % in all samples</td><td><strong>错在哪里</strong>（按错误类型聚合）</td></tr><tr><td><code>Top 5 Errors by sampler</code></td><td>Sample · #Samples · #Errors · Error（后面按 Top 5 错误类型各一组 #Errors / Error）</td><td><strong>哪个接口在报错</strong></td></tr></tbody></table><p><code>Errors</code> 把错误按类型聚合，<code>% in errors</code> 表示这种错占全部错误的百分比——如果它是 100%，说明只有单一原因，通常最好查。<code>Top 5 Errors by sampler</code> 则按接口分行，能一眼定位是登录、业务还是清理出的问题。</p><p>我们这份报告里，<code>Errors</code> 是<strong>空的</strong>（<code>items: []</code>），<code>Top 5 Errors by sampler</code> 只有一行 <code>Total</code>、<code>#Errors</code> 为 0——正对应上面的 FAIL = 0。反过来说，哪天你发现这两张表有内容了，就是它们出场的时候。</p><blockquote><p>注意：<code>FAIL</code> 只统计「请求层面」的失败。如果被测接口返回 200 但业务逻辑挂了（比如 <code>success: false</code>），FAIL 依然是 0。所以响应断言、JSON 断言该加还是要加，否则报告会「一片绿」。</p></blockquote><h3 id="平均值与中位数-average-median" tabindex="-1">平均值与中位数（Average / Median） <a class="header-anchor" href="#平均值与中位数-average-median" aria-label="Permalink to &quot;平均值与中位数（Average / Median）&quot;">​</a></h3><p><strong>平均值</strong>是把所有请求的耗时加起来除以个数，三档是 <strong>0.58 / 1.18 / 3.04ms</strong>；**中位数（Median）**是把请求按耗时排队后正中间那个，三档是 <strong>1 / 1 / 3ms</strong>。</p><p>平均值最直观，中位数更「抗干扰」（一半样本在它下面、一半在上面）。<strong>两个数摆在一起，就能看出分布的形状</strong>：</p><table tabindex="0"><thead><tr><th>档位</th><th>平均值</th><th>中位数</th><th>关系</th></tr></thead><tbody><tr><td>10</td><td>0.58ms</td><td>1ms</td><td>平均值 &lt; 中位数</td></tr><tr><td>20</td><td>1.18ms</td><td>1ms</td><td>平均值 ≈ 中位数</td></tr><tr><td>50</td><td>3.04ms</td><td>3ms</td><td>平均值 ≈ 中位数</td></tr></tbody></table><p>10 并发那档平均值反而低于中位数，说明有大量请求落在 0ms，把平均值拉了下去。</p><h3 id="最小值-最大值-min-max" tabindex="-1">最小值 / 最大值（Min / Max） <a class="header-anchor" href="#最小值-最大值-min-max" aria-label="Permalink to &quot;最小值 / 最大值（Min / Max）&quot;">​</a></h3><p>单位都是毫秒（ms）。</p><table tabindex="0"><thead><tr><th>档位</th><th>最小</th><th>最大</th></tr></thead><tbody><tr><td>10</td><td>0</td><td>5</td></tr><tr><td>20</td><td>0</td><td>26</td></tr><tr><td>50</td><td>0</td><td>14</td></tr></tbody></table><ul><li><strong>最小 0ms</strong>：不代表「瞬间完成」，只是请求快到计时器的精度以下了。这个数基本上可以忽略。</li><li><strong>最大值</strong>：最慢的那一次。<strong>这一列最容易骗人</strong>——注意 20 并发那档最大值 26ms，反而比 50 并发的 14ms 还大。线程数翻了 2.5 倍，最慢的一次却更快，说明最大值是由个别抖动（GC、调度、网络）决定的，不代表系统的处理能力。</li></ul><h3 id="标准偏差与平均字节数-只有汇总报告有" tabindex="-1">标准偏差与平均字节数（只有汇总报告有） <a class="header-anchor" href="#标准偏差与平均字节数-只有汇总报告有" aria-label="Permalink to &quot;标准偏差与平均字节数（只有汇总报告有）&quot;">​</a></h3><p>第二节列汇总报告时出现过的这两列，<strong>HTML 报告的 Statistics 表里并没有</strong>，只在 GUI 的汇总报告里有，所以单独说一下。</p><p>**标准偏差（Std. Dev.）**衡量响应时间围绕平均值有多分散：值越大，说明快的快、慢的慢。三档是 <strong>0.57 / 0.81 / 1.26ms</strong>。</p><p>它最有用的地方是<strong>给平均值当旁证</strong>：如果标准偏差比平均值还大，说明分布很散（长尾或双峰），这时候平均值单独看会失真。我们这三档标准偏差都小于平均值，说明数据整体还算集中。</p><blockquote><p>不过也要注意尺度：10 并发那档标准差 0.57ms 和平均值 0.58ms 几乎相等，看着吓人，其实只是因为响应时间都落在 0~2ms 这种整数刻度上——<strong>在毫秒以下谈标准偏差，意义不大</strong>。</p></blockquote><p>**平均字节数（Avg. Bytes）**是每个响应的平均大小，等于响应总字节数除以样本数，三档都是 <strong>343 字节</strong>（请求体则是 251 字节）。</p><p>它的用处是<strong>反推带宽</strong>：平均字节数 × 吞吐量，就该约等于报告里的 <code>Received KB/sec</code>。验证一下 10 并发那档：343 × 13,027 ≈ 4,468,000 字节/秒，再除以 1024（JMeter 的 KB 按 1024 算），得到 <strong>4,363 KB/s</strong>——和报告里的 4,363.43 几乎完全吻合。<strong>接口返回体突然变大时，这一列会立刻反映出来</strong>，比翻日志快。</p><h3 id="_90th-95th-99th-百分位-p90-p95-p99" tabindex="-1">90th / 95th / 99th 百分位（P90 / P95 / P99） <a class="header-anchor" href="#_90th-95th-99th-百分位-p90-p95-p99" aria-label="Permalink to &quot;90th / 95th / 99th 百分位（P90 / P95 / P99）&quot;">​</a></h3><p>对应 Statistics 表里的 <code>90th pct</code> <code>95th pct</code> <code>99th pct</code> 三列（GUI 的聚合报告里叫「90% 百分位」等）。</p><table tabindex="0"><thead><tr><th>档位</th><th>P90</th><th>P95</th><th>P99</th></tr></thead><tbody><tr><td>10</td><td>1</td><td>1</td><td>2</td></tr><tr><td>20</td><td>2</td><td>3</td><td>3</td></tr><tr><td>50</td><td>5</td><td>5</td><td>7</td></tr></tbody></table><p>含义很直白：<strong>50 并发那档，95% 的请求都在 5ms 内完成</strong>。</p><p>为什么报告要给分位数，而不是只给平均值？因为平均值会被长尾稀释。举个极端例子：100 个请求里 99 个是 100ms、1 个卡了 10 秒，平均值算出来 199ms，但 P90 只有 100ms——真实体感是「几乎所有人都很快，只有一个人倒了霉」，而平均值把这个故事讲成了「大家都要等 199ms」。</p><p><strong>分位数比平均值更接近「用户实际感受到的速度」</strong>，这也是压测报告里最该先看的一列。</p><p><img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-10-b-response-times.webp" alt="响应时间随时间变化"></p><blockquote><p>同一份数据，上面几个数是把所有请求<strong>揉在一起</strong>看，这张图是<strong>按时间摊开</strong>看。摊开才看得出响应时间是「一直平稳」还是「越跑越慢」——后者往往意味着有资源在累积。</p></blockquote><p>同一片区域还有一张 <strong>Response Time Percentiles Over Time</strong>（标题注明了 <em>successful requests only</em>）——把 P90 / P95 / P99 画成随时间变化的曲线。前面那张画的是平均值，这张画的是分位数，<strong>看长尾有没有恶化，分位数那张更直接</strong>。</p><p>这两张图的价值，用 50 并发那档的 <code>.jtl</code> 按秒拆开就明白了：</p><table tabindex="0"><thead><tr><th>第几秒</th><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th><th>6</th><th>7</th><th>8</th><th>9</th><th>10</th></tr></thead><tbody><tr><td>平均</td><td>0.73ms</td><td>1.22ms</td><td>1.77ms</td><td>2.54ms</td><td>3.13ms</td><td>3.56ms</td><td>3.64ms</td><td>3.73ms</td><td>3.57ms</td><td>3.64ms</td></tr><tr><td>样本数</td><td>2,589</td><td>9,227</td><td>12,116</td><td>12,368</td><td>13,279</td><td>13,850</td><td>13,688</td><td>13,366</td><td>13,941</td><td>13,677</td></tr></tbody></table><p>前 5 秒样本数从 2,589 爬升到 13,279、响应时间从 0.73ms 抬到 3.13ms，正是 <strong>Ramp-Up 阶段线程陆续起满</strong>的过程；第 6 秒起进入稳态，样本数稳定在 1.37 万/秒左右，响应时间稳定在 3.5~3.7ms。</p><p><strong>这意味着前 5 秒的数字偏乐观，不该拿来下结论。</strong> 而汇总表把整个 10 秒揉成一个数，恰好把这个形态抹平了——这就是「看表也要看图」的原因。</p><h3 id="延迟与连接时间-latency-connect-time" tabindex="-1">延迟与连接时间（Latency / Connect Time） <a class="header-anchor" href="#延迟与连接时间-latency-connect-time" aria-label="Permalink to &quot;延迟与连接时间（Latency / Connect Time）&quot;">​</a></h3><p>报告里还有两个容易和响应时间混淆的指标。<strong>Statistics 表里没有这两列</strong>，要去图表区看（<code>Latencies Over Time</code>、<code>Connect Time Over Time</code>；<code>.jtl</code> 里是 <code>Latency</code>、<code>Connect</code> 两列）：</p><ul><li><strong>延迟（Latency）</strong>：从发出请求到收到<strong>第一个字节</strong>的时间，也就是常说的 TTFB</li><li><strong>连接时间（Connect Time）</strong>：建立 TCP 连接花的时间</li></ul><p>它们和响应时间的关系是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>响应时间 = 延迟 + 接收响应体的时间</span></span>
<span class="line"><span>延迟    = 连接时间 + 服务器处理时间（简化说法）</span></span></code></pre></div><p>也就是说，<strong>响应时间一定 ≥ 延迟</strong>，两者的差额就是响应体传输占用的时间。</p><p>那这次的数据呢？我从 <code>.jtl</code> 里算了业务行：</p><table tabindex="0"><thead><tr><th>档位</th><th>平均响应时间</th><th>平均延迟</th><th>平均连接时间</th></tr></thead><tbody><tr><td>10</td><td>0.58ms</td><td>0.58ms</td><td>0.00ms</td></tr><tr><td>20</td><td>1.18ms</td><td>1.18ms</td><td>0.00ms</td></tr><tr><td>50</td><td>3.04ms</td><td>3.04ms</td><td>0.00ms</td></tr></tbody></table><p><strong>两个数完全相等，连接时间几乎是 0。</strong> 这不奇怪：本机 loopback 没有网络传输，响应体只有 343 字节，和第一个字节一起就到了；连接时间接近 0 则是因为 HTTP 连接被复用（keep-alive）——13 万个样本里只有 <strong>5 个</strong>重新建了连接（最大 1ms），50 并发那档也只有 23 个。</p><p>所以在本机压测里，这两个指标不提供额外信息，<strong>先忽略没问题</strong>。但换成公网服务就不一样了：延迟会明显小于响应时间，<strong>差额就是传输时间</strong>——如果这个差额很大，说明瓶颈在链路或带宽，而不是服务端处理能力。这是判断「该优化服务端还是该加带宽」的一个切入口。</p><h3 id="吞吐量-transactions-s" tabindex="-1">吞吐量（Transactions/s） <a class="header-anchor" href="#吞吐量-transactions-s" aria-label="Permalink to &quot;吞吐量（Transactions/s）&quot;">​</a></h3><p>每秒完成的请求数，三档是 <strong>13,027 / 12,766 / 12,321 req/s</strong>。</p><blockquote><p>这一列在 GUI 的汇总报告里叫「吞吐量」，在 HTML 报告里叫 <code>Transactions/s</code>，指的都是同一个东西。</p></blockquote><p>它回答的是「这台机器一秒钟能扛多少活」，和并发数不是一回事：并发是「同时有多少人在等」，吞吐量是「一秒实际交付了多少」。</p><p>两者通过响应时间关联，有个很直观的关系：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>吞吐量 ≈ 并发数 / 平均响应时间</span></span></code></pre></div><p>拿 10 并发那档验证：10 / 0.000578 ≈ 17,300，实测 13,027，量级一致（差的部分是客户端和网络开销，不是所有线程都在服务端排队）。</p><h3 id="网络-接收-发送-received-sent" tabindex="-1">网络：接收 / 发送（Received / Sent） <a class="header-anchor" href="#网络-接收-发送-received-sent" aria-label="Permalink to &quot;网络：接收 / 发送（Received / Sent）&quot;">​</a></h3><p>这两列分别是服务器每秒吐回客户端、和客户端每秒发出去的数据量，单位 KB/sec：</p><table tabindex="0"><thead><tr><th>档位</th><th>Received</th><th>Sent</th><th>合计</th></tr></thead><tbody><tr><td>10</td><td>4,363</td><td>3,193</td><td>7,556 KB/s</td></tr><tr><td>20</td><td>4,276</td><td>3,129</td><td>7,405 KB/s</td></tr><tr><td>50</td><td>4,127</td><td>3,020</td><td>7,147 KB/s</td></tr></tbody></table><p>看着只是「每秒几千 KB」，换算成带宽，<strong>收发合计约 7.4 MB/s，也就是 60 Mbps 出头</strong>——单次请求的响应体只有 343 字节，但一秒发一万多次，量就上来了。</p><p>这两列主要用来判断<strong>瓶颈会不会出在网络上</strong>。这次是本机 loopback，带宽不构成限制；如果换成对公网服务，光下行这一边就有 <strong>约 35 Mbps</strong>，得确认服务器带宽够不够。</p><h3 id="apdex-把响应时间换算成一个分数" tabindex="-1">APDEX：把响应时间换算成一个分数 <a class="header-anchor" href="#apdex-把响应时间换算成一个分数" aria-label="Permalink to &quot;APDEX：把响应时间换算成一个分数&quot;">​</a></h3><p>HTML 报告最上面还有个 APDEX（Application Performance Index）面板，这次几行全是 <strong>1.000</strong>。</p><p>它把「响应时间」翻译成一个 0~1 的满意度分数，只需要两个阈值：</p><ul><li><strong>T（可容忍阈值）</strong>：这次是 <strong>500ms</strong>，请求在这个时间内完成算「满意」</li><li><strong>F（失望阈值）</strong>：这次是 <strong>1500ms</strong>，超过就算「失望」</li><li>落在 T 和 F 之间的算「可容忍」</li></ul><p>大致算法是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>APDEX = (满意数 + 可容忍数 ÷ 2) ÷ 总请求数</span></span></code></pre></div><p>1.000 意味着所有请求都在 500ms 内完成。<strong>APDEX 适合汇报给非技术同事</strong>——它把一堆毫秒数收敛成一个「体验好不好」的分数，比让人理解 P95 容易得多。</p><blockquote><p>T 和 F 可以在 <code>jmeter.properties</code> 里按业务调整：<code>apdex_satisfied_threshold</code> / <code>apdex_tolerated_threshold</code>，默认 500ms / 1500ms。对「导出报表」这类重操作，这个默认值明显偏严，按接口类型分别设定才有意义。</p></blockquote><h3 id="服务器资源-报告之外的事" tabindex="-1">服务器资源：报告之外的事 <a class="header-anchor" href="#服务器资源-报告之外的事" aria-label="Permalink to &quot;服务器资源：报告之外的事&quot;">​</a></h3><p>JMeter 报告只反映「客户端观察到的结果」，至于服务器 CPU 是不是打满了、内存是不是在涨、磁盘 IO 忙不忙，报告里看不到——需要另配监控（服务器上的 <code>top</code>、<code>vmstat</code>、<code>iostat</code>，或平台自带的监控面板）。</p><p>看资源指标时，有个比「CPU 使用率」更值得关注的数是<strong>负载（load average）</strong>：它统计排队等 CPU 的任务数。4 核机器负载 ≤ 4 说明 CPU 基本够用，持续 &gt; 4 才是真在排队。使用率 100% 但没排队其实还扛得住，<strong>负载飙高才是真瓶颈</strong>。</p><h2 id="四、三档摆在一起" tabindex="-1">四、三档摆在一起 <a class="header-anchor" href="#四、三档摆在一起" aria-label="Permalink to &quot;四、三档摆在一起&quot;">​</a></h2><p>单看一档报告只能知道「这次跑了多少」，把三档并排放才有信息量。</p><p>业务接口 <code>POST /api/perf/generate</code> 的三档数据：</p><table tabindex="0"><thead><tr><th>档位</th><th>样本数</th><th>异常%</th><th>平均</th><th>中位数</th><th>最大</th><th>P90</th><th>P95</th><th>P99</th><th>吞吐量/s</th></tr></thead><tbody><tr><td>10</td><td>130,280</td><td>0.0%</td><td>0.58ms</td><td>1ms</td><td>5ms</td><td>1ms</td><td>1ms</td><td>2ms</td><td>13,027</td></tr><tr><td>20</td><td>127,700</td><td>0.0%</td><td>1.18ms</td><td>1ms</td><td>26ms</td><td>2ms</td><td>3ms</td><td>3ms</td><td>12,766</td></tr><tr><td>50</td><td>123,486</td><td>0.0%</td><td>3.04ms</td><td>3ms</td><td>14ms</td><td>5ms</td><td>5ms</td><td>7ms</td><td>12,321</td></tr></tbody></table><p>一眼能看出来的事：</p><ul><li><strong>错误率全程为 0</strong>，系统在 50 并发下是可用的</li><li><strong>延迟随并发稳步上涨</strong>：平均 0.58 → 1.18 → 3.04ms，P95 从 1ms 涨到 5ms</li><li><strong>吞吐量几乎不动</strong>：13,027 → 12,766 → 12,321，甚至略微下降</li></ul><p>「并发翻 5 倍，吞吐却没涨」听起来像坏消息，但它其实是压测最有价值的发现——说明<strong>系统在 10 并发时就已经接近处理上限，后面加线程只是让请求排队</strong>。这部分推理过程（含每秒明细和排队论的验证）写在《用 JMeter 压一把接口》里，这里不重复。</p><p>对「指标解读」来说，记住结论就够了：<strong>吞吐量不再随并发上涨，就是拐点到了</strong>。</p><h2 id="五、四个最容易读错的地方" tabindex="-1">五、四个最容易读错的地方 <a class="header-anchor" href="#五、四个最容易读错的地方" aria-label="Permalink to &quot;五、四个最容易读错的地方&quot;">​</a></h2><h3 id="_1-平均值不等于大多数人的体验" tabindex="-1">1. 平均值不等于大多数人的体验 <a class="header-anchor" href="#_1-平均值不等于大多数人的体验" aria-label="Permalink to &quot;1. 平均值不等于大多数人的体验&quot;">​</a></h3><p>上面那张「平均值 / 中位数」对照表就是例子：同一批数据，两个数的关系会随分布形状变化。</p><p><strong>平均值可以用来看趋势，但别用它回答「大多数人要等多久」</strong>——要回答那个问题，看中位数和 P90。</p><h3 id="_2-最大值最容易被个别抖动带偏" tabindex="-1">2. 最大值最容易被个别抖动带偏 <a class="header-anchor" href="#_2-最大值最容易被个别抖动带偏" aria-label="Permalink to &quot;2. 最大值最容易被个别抖动带偏&quot;">​</a></h3><p>前面提过：20 并发最大值 26ms，比 50 并发的 14ms 还大。把两张表摆在一起看：</p><p><img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-07-report-20.webp" alt="20 并发 HTML 报告 Statistics"></p><p><img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-08-report-50.webp" alt="50 并发 HTML 报告 Statistics"></p><p>如果只盯最大值，很容易得出「20 并发比 50 并发还慢」的荒谬结论。<strong>最大值适合用来发现「有没有异常请求」，不适合用来比较档位之间的性能。</strong></p><h3 id="_3-样本数虚高-不代表真的并发了" tabindex="-1">3. 样本数虚高，不代表真的并发了 <a class="header-anchor" href="#_3-样本数虚高-不代表真的并发了" aria-label="Permalink to &quot;3. 样本数虚高，不代表真的并发了&quot;">​</a></h3><p>样本数多只说明「发了很多请求」，不能说明「同时在发」——前面讲样本数时举的「线程 10、样本数也刚好 10」就是一例。</p><p><strong>判断方法</strong>：看 HTML 报告里的 <strong>Active Threads Over Time</strong>，或直接翻 <code>.jtl</code> 的 <code>grpThreads</code> 列（当前活跃线程数）。<strong>曲线没爬到目标线程数，后面的延迟和吞吐都不可信。</strong> 本机跑尤其要确认这一条——JMeter 和被测服务抢同一台机器的 CPU，最容易出现「线程还没起满，时间就到了」。</p><h3 id="_4-吞吐量不涨-不等于系统变差了" tabindex="-1">4. 吞吐量不涨，不等于系统变差了 <a class="header-anchor" href="#_4-吞吐量不涨-不等于系统变差了" aria-label="Permalink to &quot;4. 吞吐量不涨，不等于系统变差了&quot;">​</a></h3><p>看到「并发从 10 加到 50，吞吐反而降了」，容易得出「并发越高越差」的结论。</p><p>但前面那张三档汇总表里，两个数差了不到 6%，属于同一水平；真正变化的是延迟（涨了 5 倍）。准确的说法是：<strong>系统早就到顶了，多出来的并发只能排队等待，表现出来就是延迟上升</strong>——这是压测要的结果，不是坏消息。</p><h2 id="六、拿到报告先看什么" tabindex="-1">六、拿到报告先看什么 <a class="header-anchor" href="#六、拿到报告先看什么" aria-label="Permalink to &quot;六、拿到报告先看什么&quot;">​</a></h2><p>按这个顺序看，不容易被带偏：</p><ol><li><strong>先看异常%</strong>——非 0 就直接翻 <code>Errors</code> 和 <code>Top 5 Errors by sampler</code> 两张表，别的都放一边</li><li><strong>再看 P90 / P95</strong>——别只信平均值，长尾会骗人</li><li><strong>看样本数和活跃线程</strong>——确认并发是不是真的起来了</li><li><strong>看吞吐量随并发的走势</strong>——涨就是还有余量，走平就说明到拐点了</li><li><strong>对照服务器资源</strong>——CPU 负载、内存、IO 是不是已经顶满</li><li><strong>留意反常数据点</strong>——像最大值倒挂、某档吞吐断崖这类，要么是环境抖动，要么藏着真问题</li></ol><h2 id="七、术语速查" tabindex="-1">七、术语速查 <a class="header-anchor" href="#七、术语速查" aria-label="Permalink to &quot;七、术语速查&quot;">​</a></h2><p>同一个指标，在三种视图里叫法不一样，混着说最容易对不上。下表按「中文说法」索引：</p><table tabindex="0"><thead><tr><th>中文说法</th><th>GUI 汇总报告</th><th>GUI 聚合报告</th><th>HTML 报告</th><th><code>.jtl</code> 字段</th></tr></thead><tbody><tr><td>样本数</td><td># 样本</td><td># 样本</td><td>#Samples</td><td>每个样本一行</td></tr><tr><td>失败数</td><td>—</td><td>—</td><td>FAIL</td><td><code>success=false</code> 的计数</td></tr><tr><td>异常率</td><td>异常 %</td><td>异常 %</td><td>Error %</td><td>—</td></tr><tr><td>平均响应时间</td><td>平均值</td><td>平均值</td><td>Average</td><td><code>elapsed</code></td></tr><tr><td>中位数</td><td>—</td><td>中位数</td><td>Median</td><td>—</td></tr><tr><td>百分位</td><td>—</td><td>90% / 95% / 99% 百分位</td><td>90th / 95th / 99th pct</td><td>—</td></tr><tr><td>最小值 / 最大值</td><td>最小值 / 最大值</td><td>最小值 / 最大值</td><td>Min / Max</td><td><code>elapsed</code></td></tr><tr><td>标准偏差</td><td>标准偏差</td><td>—</td><td>—</td><td>—</td></tr><tr><td>平均字节数</td><td>平均字节数</td><td>—</td><td>—</td><td><code>bytes</code></td></tr><tr><td>吞吐量</td><td>吞吐量</td><td>吞吐量</td><td>Transactions/s</td><td>—</td></tr><tr><td>接收 / 发送</td><td>接收 / 发送 KB/sec</td><td>接收 / 发送 KB/sec</td><td>Received / Sent</td><td><code>bytes</code> / <code>sentBytes</code></td></tr><tr><td>延迟（TTFB）</td><td>—</td><td>—</td><td>只有图表</td><td><code>Latency</code></td></tr><tr><td>连接时间</td><td>—</td><td>—</td><td>只有图表</td><td><code>Connect</code></td></tr><tr><td>活跃线程数</td><td>—</td><td>—</td><td>只有图表</td><td><code>grpThreads</code> / <code>allThreads</code></td></tr></tbody></table><p>两个容易记混的点：</p><ul><li><strong>「—」不等于没这个指标</strong>。比如失败数只在 HTML 报告里作为独立列存在，GUI 两种报告都只给「异常 %」；延迟和连接时间在任何表里都没有，只有图表。</li><li><strong><code>.jtl</code> 才是原始数据</strong>，列名以英文为准。报告里算出来的中位数、百分位，都是从 <code>elapsed</code> 这一列推出来的，原始文件里并不存在。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>一份压测报告里，<strong>异常% 决定「能不能用」，P90/P95 决定「用得爽不爽」，吞吐量决定「能扛多少」</strong>。平均值和最大值都会骗人，前者被长尾稀释、后者被个别抖动带偏。</p><p>而三档数据并排看，才能看出系统是在「还没吃饱」还是「已经排队」——后者，就是压测真正要找的那个点。</p>`,131)])])}const m=d(r,[["render",a]]);export{g as __pageData,m as default};
